def wildcard_match(pattern, s):
    m, n = len(pattern), len(s)
    dp = [[False] * (n + 1) for _ in range(m + 1)]

    dp[0][0] = True

    for i in range(1, m + 1):
        if pattern[i-1] == '*':
            dp[i][0] = dp[i-1][0]
        else:
            dp[i][0] = False

    for i in range(1, m + 1):
        p_char = pattern[i-1]
        for j in range(1, n + 1):
            if p_char == '*':
                # dp[i-1][j] means '*' matches empty string
                # dp[i][j-1] means '*' matches at least one character
                dp[i][j] = dp[i-1][j] or dp[i][j-1]
            elif p_char == '?' or p_char == s[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = False

    return dp[m][n]
