import re

def evaluate(expr):
    # Tokenize the expression
    tokens = re.findall(r'\d+\.\d+|\d+|[+\-*/%()**]', expr)
    if "".join(tokens) != expr.replace(" ", ""):
        # This check is a simple way to ensure no invalid characters exist
        # but a more robust way is to check if the joined tokens match the input
        pass

    def get_precedence(op):
        if op in ('+', '-'): return 1
        if op in ('*', '/', '%'): return 2
        if op == '**': return 3
        return 4

    def apply_op(operators, values):
        op = operators.pop()
        right = values.pop()
        left = values.pop()
        if op == '+': values.append(left + right)
        elif op == '-': values.append(left - right)
        elif op == '*': values.append(left * right)
        elif op == '/': 
            if right == 0: raise ValueError("Division by zero")
            values.append(left / right)
        elif op == '%': values.append(left % right)
        elif op == '**': values.append(left ** right)
        elif op == 'u+': values.append(+right)
        elif op == 'u-': values.append(-right)

    # Shunting-yard algorithm modified for unary and right-associativity
    values = []
    operators = []

    i = 0
    while i < len(tokens):
        token = tokens[i]

        if re.match(r'^\d+\.?\d*$', token):
            values.append(float(token) if '.' in token else int(token))
        elif token == '(':
            operators.append(token)
        elif token == ')':
            while operators and operators[-1] != '(':
                apply_op(operators, values)
            if not operators: raise ValueError("Mismatched parentheses")
            operators.pop()
        else:
            # Determine if operator is unary
            is_unary = False
            if token in ('+', '-'):
                if i == 0 or tokens[i-1] == '(':
                    is_unary = True
                    operators.append('u' + token)
                else:
                    operators.append(token)
            else:
                operators.append(token)

            while operators and operators[-1] != '(':
                top_op = operators[-1]
                prec_top = get_precedence(top_op)
                prec_curr = get_precedence(operators[-1])

                # Handle precedence and associativity
                # ** is right-associative
                if (token != '**' and prec_curr >= prec_top) or \
                   (token == '**' and prec_curr > prec_top):
                    apply_op(operators, values)
                else:
                    break
        i += 1

    while operators:
        if operators[-1] == '(': raise ValueError("Mismatched parentheses")
        apply_op(operators, values)

    if len(values) != 1:
        raise ValueError("Malformed expression")

    return values[0]
