function createStore(reducer, initial) {
  let state = initial;
  let listeners = [];
  let isDispatching = false;

  const getState = () => state;

  const dispatch = (action) => {
    if (isDispatching) {
      throw new Error("Reducers, middleware, and other dispatch calls are not allowed.");
    }

    isDispatching = true;
    try {
      const nextState = reducer(state, action);
      state = nextState;

      const snapshot = [...listeners];
      for (let i = 0; i < snapshot.length; i++) {
        const listener = snapshot[i];
        listener();
      }
    } finally {
      isDispatching = false;
    }
    return action;
  };

  const subscribe = (fn) => {
    listeners.push(fn);
    return () => {
      listeners = listeners.filter((l) => l !== fn);
    };
  };

  return {
    getState,
    dispatch,
    subscribe,
  };
}

module.exports = createStore;
